const toggle=document.querySelector('.menu-toggle');const nav=document.querySelector('#navigation');toggle?.addEventListener('click',()=>{const open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));toggle.setAttribute('aria-label',open?'Zapri meni':'Odpri meni');toggle.textContent=open?'×':'☰';nav.classList.toggle('open',open)});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&nav?.classList.contains('open')){toggle.click();toggle.focus()}});
const form=document.querySelector('#brief-form');let brief='';if(form){const query=new URLSearchParams(location.search).get('storitev');const map={'01':'Nova spletna stran','02':'Prenova strani','03':'Pametne rešitve','04':'Vzdrževanje'};if(map[query])for(const radio of form.querySelectorAll('[name=storitev]'))radio.checked=radio.value===map[query];form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const data=new FormData(form);brief=`WEXA — Povzetek projekta\n\nIme: ${data.get('ime').trim()}\nE-pošta: ${data.get('email').trim()}\nPodjetje: ${data.get('podjetje').trim()||'Ni navedeno'}\nStoritev: ${data.get('storitev')}\n\nOpis projekta:\n${data.get('opis').trim()}\n\nTa povzetek še ni bil poslan podjetju WEXA.`;document.querySelector('#brief-text').textContent=brief;document.querySelector('#brief-result').hidden=false;document.querySelector('#brief-result').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'nearest'});});document.querySelector('#download-brief').addEventListener('click',()=>{const url=URL.createObjectURL(new Blob([brief],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='WEXA-povzetek-projekta.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)});document.querySelector('#copy-brief').addEventListener('click',async()=>{try{await navigator.clipboard.writeText(brief);document.querySelector('#copy-status').textContent='Povzetek je kopiran.'}catch{document.querySelector('#copy-status').textContent='Kopiranje ni na voljo. Prenesite povzetek ali označite in kopirajte besedilo.'}})}

// Same-origin preview: animate only while the card is actively inspected.
document.querySelectorAll('.live-preview').forEach(preview=>{
 const card=preview.closest('a.project'),iframe=preview.querySelector('iframe');
 const motion=matchMedia('(prefers-reduced-motion: reduce)'),hover=matchMedia('(hover: hover)');
 let hovered=false,focused=false,visible=true;
 const send=()=>{const active=visible&&!document.hidden&&!motion.matches&&((hover.matches&&hovered)||focused);iframe.contentWindow?.postMessage({type:'wexa-preview-motion',active},location.origin==='null'?'*':location.origin)};
 const fit=()=>preview.style.setProperty('--preview-scale',String(preview.clientWidth/1280));fit();new ResizeObserver(fit).observe(preview);
 iframe.addEventListener('load',()=>{preview.classList.add('is-ready');fit();send()});
 card.addEventListener('pointerenter',()=>{hovered=true;send()});card.addEventListener('pointerleave',()=>{hovered=false;send()});
 card.addEventListener('focus',()=>{focused=card.matches(':focus-visible');send()});card.addEventListener('blur',()=>{focused=false;send()});
 new IntersectionObserver(entries=>{visible=entries[0].isIntersecting;send()}).observe(preview);
 document.addEventListener('visibilitychange',send);motion.addEventListener('change',send);hover.addEventListener('change',send);
});


(()=>{const c=document.querySelector('#fx'),x=c.getContext('2d');if(!x)return;let w,h,t=0,last=0,raf=0;const reduced=matchMedia('(prefers-reduced-motion:reduce)');function resize(){w=innerWidth;h=innerHeight;const d=innerWidth<800?.75:1;c.width=w*d;c.height=h*d;x.setTransform(d,0,0,d,0,0)}resize();addEventListener('resize',resize);let px=.5,py=.5;addEventListener('pointermove',e=>{px=e.clientX/w;py=e.clientY/h});function draw(now){if(now-last>(innerWidth<800?50:33)){t+=.012;last=now;x.clearRect(0,0,w,h);if(3===2){x.fillStyle='#eef5ff';x.fillRect(0,0,w,h);for(let i=0;i<38;i++){x.beginPath();for(let j=0;j<=100;j++){let a=j/100;let yy=h*.5+Math.sin(a*5+t+i*.075)*h*.2+Math.cos(a*9-t*.7+i*.09)*h*.08+i*9-h*.17;let xx=a*w;if(j)x.lineTo(xx,yy+(py-.5)*20);else x.moveTo(xx,yy)}x.strokeStyle='rgba(35,95,235,'+(i%5===0?.3:.11)+')';x.lineWidth=i%5===0?1.6:.8;x.stroke()}let g=x.createRadialGradient(w*.8,h*.3,0,w*.8,h*.3,w*.65);g.addColorStop(0,'#ffffff99');g.addColorStop(1,'#ffffff00');x.fillStyle=g;x.fillRect(0,0,w,h)}else{x.fillStyle='#060f27';x.fillRect(0,0,w,h);x.globalCompositeOperation='screen';for(let k=0;k<4;k++){let xx=w*(.15+k*.25)+Math.sin(t*.6+k)*w*.13+(px-.5)*35,yy=h*(.4+Math.sin(t*.5+k*2)*.27);let g=x.createRadialGradient(xx,yy,0,xx,yy,w*.48);g.addColorStop(0,['#124dcf99','#6728c599','#04a0be77','#163bde99'][k]);g.addColorStop(1,'#00000000');x.fillStyle=g;x.fillRect(0,0,w,h)}for(let i=0;i<10;i++){x.beginPath();for(let j=0;j<=90;j++){let a=j/90,yy=h*.5+Math.sin(a*4.3+t*.6+i*.065)*h*.32+i*8;if(j)x.lineTo(a*w,yy);else x.moveTo(a*w,yy)}x.strokeStyle='rgba(109,190,255,.13)';x.lineWidth=1;x.stroke()}x.globalCompositeOperation='source-over'}}if(!reduced.matches&&!document.hidden)raf=requestAnimationFrame(draw)}function resume(){cancelAnimationFrame(raf);if(!document.hidden)raf=requestAnimationFrame(draw)}document.addEventListener('visibilitychange',resume);reduced.addEventListener('change',resume);resume()})();